const BEH=[
{e:"👑",n:{en:"Pecking order",es:"Orden jerárquico"},ok:1,t:{en:"Every flock has a ranking. Some pecking and chasing is normal, especially when new birds join. Step in if there's blood or one bird can't reach food.",es:"Toda parvada tiene jerarquía. Algo de picoteo y persecución es normal, sobre todo con aves nuevas. Interviene si hay sangre o una no alcanza la comida."}},
{e:"🛁",n:{en:"Dust bathing",es:"Baño de tierra"},ok:1,t:{en:"Flopping and flinging dirt is how they clean feathers and fight parasites. Give them a dry spot of loose soil.",es:"Revolcarse y lanzarse tierra es su forma de limpiar plumas y combatir parásitos. Dales un rincón seco de tierra suelta."}},
{e:"☀️",n:{en:"Sunbathing",es:"Tomar el sol"},ok:1,t:{en:"Lying sideways with one wing stretched out looks scary, but it's bliss. It may help with feather care.",es:"Acostada de lado con un ala extendida asusta, pero es puro placer. Puede ayudar al cuidado de las plumas."}},
{e:"🥚",n:{en:"The egg song",es:"El canto del huevo"},ok:1,t:{en:"Loud 'buck-buck-BAGAWK' after laying (or when someone is in her favorite nest). Totally normal, but loud!",es:"Un fuerte 'co-co-CORÓ' después de poner (o si alguien ocupa su nido favorito). Normal, ¡pero ruidoso!"}},
{e:"🪺",n:{en:"Broodiness",es:"Cloquera"},ok:1,t:{en:"She flattens on the nest, puffs up, growls and won't leave. She wants to hatch eggs. Give her fertile eggs, or break it by removing her from the nest and blocking it for a few days.",es:"Se aplana en el nido, se esponja, gruñe y no se va: quiere empollar. Dale huevos fértiles o córtala sacándola y bloqueando el nido unos días."}},
{e:"📣",n:{en:"Alarm calls",es:"Llamadas de alarma"},ok:1,t:{en:"A sharp cry and everyone freezes or hides, usually for a hawk overhead. Loud cackling tends to mean a ground predator. Go check!",es:"Un grito agudo y todas se congelan o esconden: suele ser un halcón. Un cacareo fuerte suele indicar depredador en tierra. ¡Ve a revisar!"}},
{e:"🐓",n:{en:"Tidbitting",es:"Llamado a la comida"},ok:1,t:{en:"A rooster or top hen clucks rapidly while picking up and dropping food to call the others over. It's sweet flock teamwork.",es:"El gallo o la gallina líder cloquea rápido mientras levanta y suelta comida para llamar a las demás. Bonito trabajo en equipo."}},
{e:"🌙",n:{en:"Roosting at dusk",es:"Subir a la percha"},ok:1,t:{en:"They put themselves to bed at sunset. Hens sleeping in nest boxes instead usually need higher roosts than the nests.",es:"Se van solas a dormir al atardecer. Si duermen en los nidales, las perchas deben estar más altas que los nidos."}},
{e:"🥴",n:{en:"Egg eating",es:"Comerse los huevos"},ok:0,t:{en:"Once started it spreads. Collect eggs often, add more calcium, use dim nests with soft bedding, and try ceramic eggs or a mustard-filled shell as a deterrent.",es:"Una vez que empieza se contagia. Recoge seguido, más calcio, nidos oscuros con cama suave y prueba huevos de cerámica o una cáscara con mostaza."}},
{e:"🪶",n:{en:"Feather pulling",es:"Arrancar plumas"},ok:0,t:{en:"Usually from boredom, crowding or low protein. Add space, enrichment and complete feed. See Health for wounds.",es:"Suele ser por aburrimiento, hacinamiento o poca proteína. Más espacio, entretenimiento y alimento completo. Ve Salud si hay heridas."}}];

const DOS=[
{d:1,e:"🧺",n:{en:"Collect eggs daily",es:"Recoge huevos a diario"},t:{en:"Fresh, clean eggs and fewer broken ones or broody hens.",es:"Huevos frescos y limpios, menos rotos y menos cluecas."}},
{d:1,e:"🔒",n:{en:"Lock up at dusk",es:"Cierra al anochecer"},t:{en:"Most predator losses happen at night. Automatic doors help.",es:"La mayoría de los ataques son de noche. Las puertas automáticas ayudan."}},
{d:1,e:"🧼",n:{en:"Wash hands after",es:"Lávate las manos"},t:{en:"Healthy-looking birds can carry Salmonella. Wash with soap after touching birds, eggs or gear (CDC).",es:"Aves que se ven sanas pueden portar Salmonella. Lava con jabón tras tocar aves, huevos o equipo (CDC)."}},
{d:1,e:"⏳",n:{en:"Quarantine newcomers",es:"Cuarentena a las nuevas"},t:{en:"Keep new birds apart for about 30 days to avoid bringing in disease and mites.",es:"Mantén aparte a las aves nuevas unos 30 días para no traer enfermedades ni ácaros."}},
{d:1,e:"💧",n:{en:"Fresh water, always",es:"Agua fresca siempre"},t:{en:"A hen without water stops laying fast. Use two waterers in case one fails.",es:"Sin agua, una gallina deja de poner rápido. Ten dos bebederos por si uno falla."}},
{d:1,e:"🐚",n:{en:"Oyster shell on the side",es:"Concha de ostión aparte"},t:{en:"Free-choice calcium for strong shells. Layers take what they need.",es:"Calcio libre para cáscaras fuertes. Las ponedoras toman lo que necesitan."}},
{d:0,e:"🕸️",n:{en:"Rely on chicken wire",es:"Confiar en malla de gallinero"},t:{en:"It keeps chickens in, not raccoons out. Use 1/2-inch hardware cloth.",es:"Mantiene adentro a las gallinas, no afuera a los mapaches. Usa malla de ferretería de 1/2 pulgada (1.3 cm)."}},
{d:0,e:"😘",n:{en:"Kiss or snuggle",es:"Besarlas o apapacharlas"},t:{en:"The CDC advises against it, and against eating or drinking around the flock.",es:"El CDC lo desaconseja, igual que comer o beber cerca de la parvada."}},
{d:0,e:"👶",n:{en:"Let kids under 5 handle chicks",es:"Dejar que menores de 5 toquen pollitos"},t:{en:"Young children get sicker from Salmonella. Supervise older kids and handwashing.",es:"Los niños pequeños enferman más por Salmonella. Supervisa a los mayores y el lavado de manos."}},
{d:0,e:"🔥",n:{en:"Heat the coop with a lamp",es:"Calentar con lámpara"},t:{en:"Heat lamps start many coop fires. Feathered adults stay warm if they're dry and out of drafts.",es:"Las lámparas causan muchos incendios. Las adultas emplumadas se calientan si están secas y sin corrientes."}},
{d:0,e:"🍞",n:{en:"Overdo treats",es:"Exagerar con los premios"},t:{en:"Stick to the 90/10 rule, or egg numbers and shells suffer.",es:"Respeta la regla 90/10, o sufren los huevos y las cáscaras."}},
{d:0,e:"🌙",n:{en:"Leave feed out at night",es:"Dejar comida de noche"},t:{en:"It invites rats and mice, which spread disease and steal eggs.",es:"Atrae ratas y ratones, que propagan enfermedades y roban huevos."}}];

const COOP=[
{e:"📐",n:{en:"Space",es:"Espacio"},t:{en:"Plan about 4 sq ft (0.4 m²) inside the coop and about 10 sq ft (1 m²) of run per standard-size bird. Crowding causes pecking and disease.",es:"Calcula unos 0.4 m² (4 pies²) dentro del gallinero y 1 m² (10 pies²) de corral por ave estándar. El hacinamiento causa picoteo y enfermedades."}},
{e:"🪵",n:{en:"Roosts",es:"Perchas"},t:{en:"About 8–12 inches (20–30 cm) of roost per bird, higher than the nest boxes. Wide, flat perches let them cover their toes in winter.",es:"Unos 20–30 cm de percha por ave, más alta que los nidales. Perchas anchas y planas les cubren los dedos en invierno."}},
{e:"🪺",n:{en:"Nest boxes",es:"Nidales"},t:{en:"About 1 box per 4–5 hens, roughly 12×12 inches (30×30 cm), dim and lined with clean bedding.",es:"Un nidal por cada 4–5 gallinas, de unos 30×30 cm, oscuro y con cama limpia."}},
{e:"🌬️",n:{en:"Ventilation",es:"Ventilación"},t:{en:"Vents up high let moist air and ammonia out. Fresh air without drafts on the roost is the key to healthy lungs and no frostbite.",es:"Ventilas altas dejan salir humedad y amoníaco. Aire fresco sin corrientes en la percha es clave para pulmones sanos y sin congelación."}},
{e:"🦝",n:{en:"Predators",es:"Depredadores"},t:{en:"Raccoons, foxes, hawks, dogs and snakes. Use hardware cloth, bury an apron of wire around the run, use two-step latches, and lock up nightly.",es:"Mapaches, zorros, halcones, perros y serpientes. Usa malla de ferretería, entierra un faldón de malla, usa seguros de dos pasos y cierra cada noche."}},
{e:"🥾",n:{en:"Biosecurity",es:"Bioseguridad"},t:{en:"Use coop-only shoes, limit visitors, keep wild birds off the feed, quarantine new birds, and buy from NPIP-certified hatcheries.",es:"Zapatos solo para el gallinero, pocas visitas, aves silvestres lejos del alimento, cuarentena y criaderos certificados NPIP."}},
{e:"💡",n:{en:"Light & laying",es:"Luz y postura"},t:{en:"Laying slows when daylight drops below about 14 hours. Added light is optional; a natural winter rest is fine.",es:"La postura baja con menos de unas 14 horas de luz. La luz extra es opcional; un descanso natural en invierno está bien."}},
{e:"🏘️",n:{en:"Local rules",es:"Reglas locales"},t:{en:"Check city or HOA rules on flock size, roosters and coop placement before you buy.",es:"Revisa las reglas de tu ciudad o asociación sobre número de aves, gallos y ubicación del gallinero antes de comprar."}}];

const FEED=[
{e:"🐣",n:{en:"Starter (0–8 weeks)",es:"Iniciador (0–8 semanas)"},t:{en:"About 18–20% protein for fast growth. Comes medicated (helps prevent coccidiosis) or not.",es:"Unas 18–20% de proteína para crecer rápido. Viene medicado (ayuda contra coccidiosis) o no."}},
{e:"🐥",n:{en:"Grower (8–18 weeks)",es:"Crecimiento (8–18 semanas)"},t:{en:"About 16–18% protein and low calcium so young kidneys aren't stressed. Many keepers use one starter/grower feed until laying.",es:"16–18% de proteína y poco calcio para no forzar los riñones. Muchos usan un solo iniciador/crecimiento hasta la postura."}},
{e:"🐔",n:{en:"Layer (from first egg)",es:"Postura (desde el primer huevo)"},t:{en:"About 16% protein with about 3.5–4% calcium for shells. Feed it only to hens that are laying; roosters and chicks do better on an all-flock feed with oyster shell on the side.",es:"Unas 16% de proteína con 3.5–4% de calcio para las cáscaras. Solo para gallinas en postura; gallos y pollitos mejor con alimento para toda la parvada y concha aparte."}},
{e:"🪨",n:{en:"Grit",es:"Grit (piedrecillas)"},t:{en:"Chickens have no teeth; tiny stones in the gizzard grind food. Needed whenever they eat more than commercial feed.",es:"No tienen dientes; piedritas en la molleja muelen la comida. Necesario si comen algo más que alimento comercial."}},
{e:"🐚",n:{en:"Calcium",es:"Calcio"},t:{en:"Free-choice oyster shell lets each hen top up. Dried, crushed eggshells work too.",es:"La concha de ostión libre deja que cada gallina complete. Cáscaras de huevo secas y molidas también sirven."}},
{e:"🫙",n:{en:"Fermented feed",es:"Alimento fermentado"},t:{en:"Soaking feed in water for a few days grows helpful bacteria. NC State Extension says it can improve gut health and nutrient absorption when managed well. Use it as a supplement, start slowly, keep feed under the water, and throw out any batch with mold, a rotten smell or odd colors.",es:"Remojar el alimento en agua unos días hace crecer bacterias benéficas. NC State Extension dice que puede mejorar la salud intestinal y la absorción si se maneja bien. Úsalo como complemento, empieza poco a poco, mantén el alimento bajo el agua y desecha cualquier tanda con moho, olor podrido o colores raros."}},
{e:"💧",n:{en:"Water",es:"Agua"},t:{en:"An egg is mostly water. Hens drink more in heat; keep water clean, shaded and unfrozen.",es:"Un huevo es casi todo agua. Beben más con calor; agua limpia, a la sombra y sin congelar."}}];

